create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.CRM_L_KUNDE_1 (
	CRM_KUNDE_ID VARCHAR(36) NOT NULL COMMENT 'CRM-interne ID des Kunden',
	ZEIT_REGISTRIERUNG TIMESTAMP_LTZ(9) COMMENT 'Registrierungsdatum des Kunden',
	ZEIT_ABMELDUNG TIMESTAMP_LTZ(9) NOT NULL COMMENT 'Abmeldedatum des Kunden - ist immer gefüllt',
	KUNDENTYP_CD VARCHAR(60) NOT NULL COMMENT 'Code des Kundentypes.',
	KUNDENHERKUNFT_CD VARCHAR(50) NOT NULL COMMENT 'Code der Kundenherkunft ( example values: K-App,Marktplatz,Mobiles Registrierungsformular,kappAndroid,kappIOS,marketplaceLoyalty,sscTerminal,sscWeb,Web).',
	GENDER_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'ID für das Geschlecht des Kunden',
	GEBURTSJAHR NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Geburtsjahr des Kunden ( example value: 08.08.1988 ) ',
	KUNDE_STATUSGRUND_ID NUMBER(38,0) NOT NULL DEFAULT -9999 COMMENT 'Statusgrund-ID des Kunden (liefert Information darüber, wieso der Kunde aktiv oder inaktiv ist (aktiv_fg))',
	STRASSE VARCHAR(100) NOT NULL COMMENT 'Straße in welcher der Kunde wohnt',
	WOHNORT VARCHAR(30) NOT NULL DEFAULT '0' COMMENT 'Ort in welchem der Kunde wohnt',
	PLZ VARCHAR(10) NOT NULL DEFAULT '0' COMMENT 'Postleitzahl (PLZ) des Ortes in welchem der Kunde wohnt',
	KUNDE_MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Land_1 des Kundenwohnorts',
	GEO_GITTER_100_NR VARCHAR(100) COMMENT 'Geografischen Koordinaten des Gitters (GEO-Gitternetz ) in der Größe 100*100, zu dem die geokodierte Adressinformation ( Längen- und Breitengrad) der Kunde gehört. Ein Geo-Gitternetz ist ein Raster aus Quadrate zur präzisen Positionsbestimmung auf der Erde.Räumliche Analysen sind nur erlaubt, wenn innerhalb eines GEO-Gitternetz mindestens 7 aktuell registrierte Kunden leben.Ist das nicht der Fall, das Gitter erhält einen Null-Value.',
	GEO_GITTER_500_NR VARCHAR(100) COMMENT 'Geografischen Koordinaten des Gitters (GEO-Gitternetz ) in der Größe 500*500, zu dem die geokodierte Adressinformation ( Längen- und Breitengrad) der Kunde gehört. Ein Geo-Gitternetz ist ein Raster aus Quadrate zur präzisen Positionsbestimmung auf der Erde.Räumliche Analysen sind nur erlaubt, wenn innerhalb eines GEO-Gitternetz mindestens 7 aktuell registrierte Kunden leben.Ist das nicht der Fall, das Gitter erhält einen Null-Value.',
	GEO_GITTER_1000_NR VARCHAR(100) COMMENT 'Geografischen Koordinaten des Gitters (GEO-Gitternetz ) in der Größe 1000*1000, zu dem die geokodierte Adressinformation ( Längen- und Breitengrad) der Kunde gehört. Ein Geo-Gitternetz ist ein Raster aus Quadrate zur präzisen Positionsbestimmung auf der Erde.Räumliche Analysen sind nur erlaubt, wenn innerhalb eines GEO-Gitternetz mindestens 7 aktuell registrierte Kunden leben.Ist das nicht der Fall, das Gitter erhält einen Null-Value.',
	VORZUGSFILIALE_WUP_ID NUMBER(38,0) NOT NULL COMMENT 'ID der präferierten Filiale',
	VORZUGSFILIALE_MANDANT_ID NUMBER(38,0) COMMENT 'Land_1 der präferierten Filiale',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	MERGE_FG NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Flag, das anzeigt ob dieser Kontakt mit einem anderen Kontakt gemerged/zusammengeführt wurde',
	REGISTRIERUNGSFILIALE_WUP_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Filiale in der sich der Kunde registriert hat. Bei physischen Kunden (Anmeldung in der Filiale) kommt diese Information aus dem \""mauellen\"" Registrierungsprozess. Bei digitalen Kunden (Anmeldung über App) kommt diese Information aus der App.',
	REGISTRIERUNGSFILIALE_MANDANT_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Mandant_1 ID zur Registrierungsfiliale',
	REGISTRIERUNGSFILIALE_NB_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer. Gehört zur registrierten Registrierungsfiliale.',
	AKTIV_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag das anzeigt, ob der Kunde aktiv oder inaktiv ist',
	HAUSHALTSGROESSE VARCHAR(20) COMMENT 'Haushaltsgröße',
	BESCHAEFTIGUNG_STATUS_ID NUMBER(38,0) DEFAULT -1 COMMENT 'Beschäftigungsstatus, sagt aus ob Kunde bspw. Schüler/in, Hausmann/frau, Angestellte/r,... ist',
	CRM_CIDAAS_ID VARCHAR(120) NOT NULL DEFAULT '-9999' COMMENT 'MS Dynamics - contact.kl_keycloakid -\n            Meldet sich Person unter Verwendung derselben Mailadresse/Mobilnummer an zwei verschiedenen K Card Programmen an, bekommt sie zwei separate Kontakte (crm_kunde_id), Konten (crm_konto_id) und separate Karten (kundenkarte_id). Beide Kontakte werden jedoch mit derselben Cidaas ID versehen.  ',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_CRM_L_KUNDE primary key (CRM_KUNDE_ID)
)COMMENT='EK_KUN - Cosmos DB CRM - CRM - Entität \""Customer\"" (Kundenstamm)'
;
